import AppKit

/// Polls NSPasteboard (it has no change notification) and reports new plain text.
/// Items marked concealed, transient or auto-generated — the nspasteboard.org
/// markers password managers use — are never reported.
final class PasteboardWatcher {
    private static let skippedTypes: Set<NSPasteboard.PasteboardType> = [
        .init("org.nspasteboard.ConcealedType"),
        .init("org.nspasteboard.TransientType"),
        .init("org.nspasteboard.AutoGeneratedType"),
    ]

    var onText: ((String) -> Void)?
    private let pasteboard = NSPasteboard.general
    private var lastChangeCount: Int
    private var timer: Timer?

    init() {
        lastChangeCount = pasteboard.changeCount
    }

    /// Callers poll every 0.5 s while a device is connected and every 2 s otherwise.
    func start(interval: TimeInterval) {
        timer?.invalidate()
        let timer = Timer(timeInterval: interval, repeats: true) { [weak self] _ in self?.poll() }
        timer.tolerance = interval / 5
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    /// Writes text received from a device without reporting it back as a local change.
    func write(_ text: String) {
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        lastChangeCount = pasteboard.changeCount
    }

    private func poll() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        let types = Set(pasteboard.types ?? [])
        guard types.isDisjoint(with: Self.skippedTypes), let text = pasteboard.string(forType: .string), !text.isEmpty else { return }
        onText?(text)
    }
}
